}
.app-rail-panel {
  opacity: 0;
  transition:
    transform var(--md-sys-motion-duration-medium2, 0.3s)
      cubic-bezier(0.2, 0, 0, 1),
    opacity var(--md-sys-motion-duration-short4, 0.2s)
      cubic-bezier(0.2, 0, 0, 1);
  width: 280px;
  height: 100%;
  transform: translate(-100%);
}
