  .app-prompt-bar {
    transition: border-radius var(--app-motion-spring-default-spatial-duration)
      var(--app-motion-spring-default-spatial);
  }
  .app-rail {
    transition: width 0s linear
      var(--app-motion-spring-default-spatial-duration);
  }
  .app-rail[data-expanded="true"] {
    transition: width;
  }
  .app-rail-panel {
    transition:
      transform var(--app-motion-spring-default-spatial-duration)
        var(--app-motion-spring-default-spatial),
      opacity var(--app-motion-spring-fast-effects-duration)
        var(--app-motion-spring-fast-effects);
  }
