.app-drawer {
  position: fixed;
  opacity: 1;
  z-index: 100;
  background: 0 0;
  border: 0;
  width: 100%;
  max-width: none;
  height: 100%;
  max-height: none;
  margin: 0;
  padding: 0;
  transition: none;
  inset: 0;
  transform: none;
}
.app-drawer[hidden] {
  display: none;
}
.app-drawer::backdrop {
  background: 0 0;
}
