  display: flex;
  overflow-x: auto;
  overscroll-behavior: contain;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  background: var(--md-sys-color-scrim);
  height: 100%;
}
@supports (color: color-mix(in lab, red, red)) {
  .app-drawer-scroller {
    background: color-mix(in srgb, var(--md-sys-color-scrim) 32%, transparent);
  }
}
.app-drawer-panel {
  scroll-snap-align: start;
  background: var(--md-sys-color-surface-container-low);
  border-radius: 0 var(--md-sys-shape-corner-large)
    var(--md-sys-shape-corner-large) 0;
  display: flex;
  flex-direction: column;
  flex: none;
  width: min(280px, 85vw);
  height: 100%;
  min-height: 0;
}
.app-drawer-header {
  display: flex;
  border-bottom: 1px solid var(--md-sys-color-outline-variant);
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px;
}
.app-drawer-title {
  font-weight: var(--app-weight-body-strong);
}
.app-drawer-close {
  display: grid;
  border-radius: var(--md-sys-shape-corner-full);
  color: var(--md-sys-color-on-surface-variant);
  background: 0 0;
  border: 0;
  flex: none;
  place-items: center;
  min-width: 48px;
  min-height: 48px;
}
.app-drawer-close:hover {
  background: var(--md-sys-color-on-surface);
}
@supports (color: color-mix(in lab, red, red)) {
  .app-drawer-close:hover {
    background: color-mix(
      in srgb,
      var(--md-sys-color-on-surface) 8%,
      transparent
    );
  }
}
.app-drawer-content {
  overflow: auto;
  flex: 1;
  min-height: 0;
}
.app-drawer-dismiss {
  scroll-snap-align: start;
  background: 0 0;
  border: 0;
  flex: none;
  width: 100vw;
  height: 100%;
}
@supports (animation-timeline: scroll()) {
  .app-drawer-scroller {
    animation: linear both app-drawer-scrim;
    animation-timeline: scroll(self inline);
  }
  @keyframes app-drawer-scrim {
    0% {
      background-color: color-mix(
        in srgb,
        var(--md-sys-color-scrim) 32%,
        transparent
      );
    }
    to {
      background-color: #0000;
    }
  }
}
.app-rail-trigger:focus-visible {
  outline: 2px solid var(--md-sys-color-primary);
  outline-offset: 2px;
}
.app-drawer-dismiss:focus-visible {
  outline: 2px solid var(--md-sys-color-primary);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .app-prompt-bar,
  .app-rail,
  .app-rail[data-expanded="true"],
  .app-rail-panel {
    transition: none;
  }
  .app-drawer-scroller {
    scroll-behavior: auto;
    animation: none;
  }
}
